void fft(std::vector<std::complex<double>> &x);

/* ------------------------------------------------------------------ */
/*  In‑place inverse FFT.
    The algorithm uses the well‑known relation

        IFFT(x) = (1/N) * conj( FFT( conj(x) ) )

    which turns the problem into a forward FFT.
    The two element‑wise passes (conjugate before and after the FFT)
    are parallelised with HPX for‑loops.
 ------------------------------------------------------------------ */
void ifft(std::vector<std::complex<double>> &x)
{
    const std::size_t n = x.size();
    if (n == 0) return;

    // ---------------------------------------------------------------
    // 1) conjugate the input
    // ---------------------------------------------------------------
    hpx::for_loop(hpx::execution::par, 0, n,
        [&](std::size_t i) {
            x[i] = std::conj(x[i]);
        });

    // ---------------------------------------------------------------
    // 2) forward FFT (assumed to be available; it may be parallel
    //    or sequential – the interface is the same)
    // ---------------------------------------------------------------
    fft(x);

    // ---------------------------------------------------------------
    // 3) conjugate again and scale by 1/N
    // ---------------------------------------------------------------
    const double inv_n = 1.0 / static_cast<double>(n);
    hpx::for_loop(hpx::execution::par, 0, n,
        [&](std::size_t i) {
            x[i] = std::conj(x[i]) * inv_n;
        });
}
